COMMENT ON COLUMN hr.promotion_request.headcount_no IS '编制编号｜敏感级别:P1-内部';
COMMENT ON COLUMN hr.promotion_request.period_or_course_no IS '周期/课程编号｜敏感级别:P1-内部';
COMMENT ON COLUMN hr.promotion_request.person_name IS '姓名｜敏感级别:P2-个人';
COMMENT ON COLUMN hr.promotion_request.person_no IS '人员/候选人编号｜敏感级别:P1-内部';
